const CACHE='still-shell-v66';
const FILES=['./','./index.html','./guide-catalog.json','./style.css?palette=46','./app.js?layout=38','./icon.svg?brand=2','./apple-touch-icon.png','./icon-192.png?brand=2','./icon-512.png?brand=2','./manifest.webmanifest?icons=3'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('activate',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);const ready=await Promise.all(FILES.map(file=>cache.match(file)));if(!ready.every(Boolean))throw Error('New app shell is incomplete; keeping existing caches.');await self.clients.claim();const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('still-shell-')&&key!==CACHE).map(key=>caches.delete(key)));})()));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;const url=new URL(event.request.url);if(url.pathname.endsWith('/guide-catalog.json')){event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok)await cache.put(event.request,response.clone());return response;}catch{return await cache.match(event.request)||Response.error();}})());return;}if(event.request.mode==='navigate'){event.respondWith((async()=>{const cache=await caches.open(CACHE);return await cache.match('./index.html')||await cache.match('./')||fetch(event.request);})());return;}event.respondWith(caches.match(event.request,{cacheName:CACHE}).then(hit=>hit||fetch(event.request)));});
